s=s[:a]+'''/**
 * Som de baixo para os exercícios, mais próximo de uma corda tocada com o dedo:
 * - ataque: um "toque" curto de ruído filtrado (o dedo na corda) + a corda;
 * - corpo: dente de serra (harmônicos) e uma senoide na fundamental (o grave do baixo);
 * - brilho que cai depressa (o filtro fecha como uma corda real perde os agudos);
 * - a nota para no fim da duração (`dur`, s), abafada, sem embolar com a próxima.
 */
export function pluckAt(at: number, midi: number, volume: number, out: AudioNode, dur = 1.4): void {
  if (volume <= 0) return;
  const ctx = getAudioContext();
  const hz = midiToHz(midi);
  const end = at + Math.max(0.08, Math.min(dur, 3));
  const stopAt = end + 0.12;

  // Corda: harmônicos filtrados + fundamental.
  const saw = ctx.createOscillator();
  saw.type = 'sawtooth';
  saw.frequency.setValueAtTime(hz, at);
  const sub = ctx.createOscillator();
  sub.type = 'sine';
  sub.frequency.setValueAtTime(hz, at);
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.Q.value = 1.1;
  const bright = Math.min(5000, hz * 12 + 600);
  filter.frequency.setValueAtTime(bright, at);
  filter.frequency.exponentialRampToValueAtTime(Math.max(180, hz * 2.2), at + 0.35);
  const sawGain = ctx.createGain();
  sawGain.gain.value = 0.55;
  const subGain = ctx.createGain();
  subGain.gain.value = 0.75;
  const env = ctx.createGain();
  saw.connect(sawGain).connect(filter);
  sub.connect(subGain).connect(filter);
  filter.connect(env).connect(out);
  env.gain.setValueAtTime(0, at);
  env.gain.linearRampToValueAtTime(volume, at + 0.005);
  env.gain.setTargetAtTime(volume * 0.45, at + 0.005, 0.12);
  env.gain.setTargetAtTime(volume * 0.18, at + 0.4, 0.9);
  env.gain.cancelAndHoldAtTime?.(end);
  env.gain.setTargetAtTime(0, end, 0.025); // abafa a corda no fim da nota

  // Toque do dedo: ruído curto em banda média.
  const len = Math.floor(ctx.sampleRate * 0.03);
  const noise = ctx.createBuffer(1, len, ctx.sampleRate);
  const d = noise.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
  const tick = ctx.createBufferSource();
  tick.buffer = noise;
  const band = ctx.createBiquadFilter();
  band.type = 'bandpass';
  band.frequency.value = 1800;
  band.Q.value = 0.9;
  const tickGain = ctx.createGain();
  tickGain.gain.value = volume * 0.35;
  tick.connect(band).connect(tickGain).connect(out);

  saw.start(at);
  sub.start(at);
  tick.start(at);
  saw.stop(stopAt);
  sub.stop(stopAt);
  saw.onended = () => {
    filter.disconnect();
    env.disconnect();
    tickGain.disconnect();
  };
}

