/**
 * Conferência visual: Palco do desafio (teclado do computador) e Harmonia com o instrumento embaixo.
 * Uso: node visual-check13.cjs <raiz do projeto> <pasta de saída das capturas>
 */
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const [root, outDir] = process.argv.slice(2);
const { _electron: electron } = require(path.join(root, 'node_modules', 'playwright'));
fs.mkdirSync(outDir, { recursive: true });
const userData = fs.mkdtempSync(path.join(os.tmpdir(), 'bf-visual-'));
fs.mkdirSync(path.join(userData, 'library'), { recursive: true });
fs.writeFileSync(path.join(userData, 'library', 'index.json'), JSON.stringify({ version: 1, songs: [] }));

(async () => {
  const app = await electron.launch({ args: [root], cwd: root, env: { ...process.env, NODE_ENV: 'production', BF_USER_DATA: userData, BF_AUDIO_SINK: 'none' } });
  const errors = [];
  try {
    const win = await app.firstWindow();
    win.on('pageerror', (e) => errors.push(String(e)));
    win.on('console', (m) => m.type() === 'error' && errors.push('console: ' + m.text()));
    await win.waitForLoadState('load');
    await win.setViewportSize({ width: 1500, height: 950 });
    await win.getByRole('button', { name: /Exercícios/ }).first().click();
    await win.getByRole('tab', { name: /Treino/ }).click();
    await win.locator('label.check.challenge input').check();
    await win.getByRole('combobox', { name: 'Como tocar no desafio' }).selectOption('keys');
    await win.getByRole('combobox', { name: 'Ritmo das notas' }).selectOption('2');
    await win.getByRole('button', { name: 'Começar' }).click();
    // Toca algumas notas certas pelo teclado (pela pista: gema mais próxima da linha).
    const t0 = Date.now();
    let presses = 0;
    while (Date.now() - t0 < 9000) {
      const lane = await win.evaluate(() => {
        // eslint-disable-next-line no-undef
        return null;
      });
      void lane;
      await win.keyboard.down('1');
      await win.keyboard.press('Enter');
      await win.keyboard.up('1');
      presses++;
      await win.waitForTimeout(240);
      if (presses === 20) await win.screenshot({ path: path.join(outDir, '01-palco-tocando.png') });
    }
    await win.getByRole('button', { name: 'Parar' }).click();
    await win.waitForTimeout(300);
    const dlg = win.getByRole('dialog');
    console.log('resultado aberto:', await dlg.count());
    if (await dlg.count()) console.log('resultado:', (await dlg.innerText()).replace(/\s+/g, ' ').slice(0, 220));
    await win.screenshot({ path: path.join(outDir, '02-resultado.png') });
    if (await dlg.count()) await dlg.getByRole('button', { name: 'Fechar' }).click();

    await win.getByRole('button', { name: /Harmonia/ }).first().click();
    await win.locator('.harmony-dock').waitFor();
    await win.getByRole('button', { name: 'Arpejo' }).click();
    await win.screenshot({ path: path.join(outDir, '03-harmonia-topo.png') });
    await win.locator('.harmony-dock').scrollIntoViewIfNeeded();
    await win.screenshot({ path: path.join(outDir, '04-harmonia-instrumento.png') });
    const order = await win.locator('.bass-order .harmony-tone-chip b').allTextContents();
    console.log('baixo (arpejo):', order.join(' '));
    const dockBelowMap = await win.evaluate(() => {
      const d = document.querySelector('.harmony-dock');
      const m = document.querySelector('.hm-card');
      return !!d && !!m && d.getBoundingClientRect().top > m.getBoundingClientRect().top;
    });
    console.log('instrumento abaixo do mapa:', dockBelowMap);
  } finally {
    console.log(errors.length ? 'FALHOU: ' + errors.join(' | ') : 'ok: sem erros na tela');
    await app.close();
